// Cosmetic only. Combat resolution and world coordinates remain in the engine.
export function drawAttack(c,f,reduced){const p=1-f.life/f.max,color=f.color,scale=1+(f.power||0)*.12,tx=f.tx??f.x,ty=f.ty??f.y,tau=Math.PI*2;const ring=(x,y,r,width=2,alpha=1)=>{c.globalAlpha=alpha;c.lineWidth=width;c.beginPath();c.arc(x,y,Math.max(.1,r),0,tau);c.stroke();};c.save();c.lineCap='round';c.strokeStyle=color;c.fillStyle=color;c.shadowColor=color;c.shadowBlur=reduced?0:10;
if(reduced){ring(tx,ty,12,2,1-p);c.restore();return;}
if(f.blast){const radius=f.radius||65;c.globalAlpha=(1-p)*.2;const glow=c.createRadialGradient(tx,ty,0,tx,ty,radius);glow.addColorStop(0,'#fff9e0');glow.addColorStop(.25,color);glow.addColorStop(1,color+'00');c.fillStyle=glow;c.beginPath();c.arc(tx,ty,radius,0,tau);c.fill();c.strokeStyle=color;ring(tx,ty,radius*Math.sqrt(p),3*scale,(1-p)*.8);for(let i=0;i<7;i++){const a=i*tau/7,rr=radius*p;c.globalAlpha=(1-p)*.8;c.fillStyle=i%2?color:'#fff2c7';c.beginPath();c.ellipse(tx+Math.cos(a)*rr,ty+Math.sin(a)*rr,3+5*(1-p),2+3*(1-p),a,0,tau);c.fill();}c.restore();return;}
const travel=Math.min(1,p/.26),x=f.x+(tx-f.x)*travel,y=f.y+(ty-f.y)*travel;c.globalAlpha=1-p;
if(f.job===0){const tail=Math.max(0,travel-.32);c.lineWidth=7*scale;c.strokeStyle=color;c.beginPath();c.moveTo(f.x+(tx-f.x)*tail,f.y+(ty-f.y)*tail);c.lineTo(x,y);c.stroke();c.lineWidth=2;c.strokeStyle='#e4fff4';c.stroke();c.fillStyle='#f6ffdc';c.beginPath();c.arc(x,y,4*scale,0,tau);c.fill();}
else if(f.job===1){const a=Math.atan2(ty-f.y,tx-f.x);c.lineWidth=3*scale;for(let i=0;i<3;i++){const rr=8+i*8;c.beginPath();c.arc(x,y,rr,a-.7,a+.7);c.stroke();}}
else if(f.job===2){c.fillStyle='#fff5d9';c.beginPath();c.arc(x,y,5*scale,0,tau);c.fill();c.strokeStyle=color;c.lineWidth=4;c.beginPath();c.moveTo(x-8,y+6);c.lineTo(x+5,y-7);c.stroke();}
else if(f.job===3){c.globalAlpha=(1-p)*.5;c.lineWidth=1.5;c.beginPath();c.moveTo(f.x,f.y);c.lineTo(tx,ty);c.stroke();c.globalAlpha=1-p;const radius=(22-10*p)*scale;c.translate(tx,ty);c.rotate(p*1.2);for(let i=0;i<4;i++){c.rotate(Math.PI/2);c.lineWidth=3;c.beginPath();c.moveTo(radius-7,-radius);c.lineTo(radius,-radius);c.lineTo(radius,-radius+7);c.stroke();}c.translate(-tx,-ty);}
if(p>.2&&f.job!==3){const q=(p-.2)/.8;c.strokeStyle=color;ring(tx,ty,5+q*22*scale,3*scale,1-q);c.strokeStyle='#fff7d8';for(let i=0;i<6;i++){const a=i*tau/6,rr=8+q*26*scale;c.globalAlpha=1-q;c.lineWidth=2;c.beginPath();c.moveTo(tx+Math.cos(a)*rr,ty+Math.sin(a)*rr);c.lineTo(tx+Math.cos(a)*(rr+6*(1-q)),ty+Math.sin(a)*(rr+6*(1-q)));c.stroke();}}
c.restore();}
